def _validate_request(data, auth_token):
    """Validate the parts of a request required before processing."""
    # Authenticate first so invalid callers cannot learn anything about the
    # request payload or trigger payload processing.
    if auth_token is None or not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")

    if data is None:
        raise ValueError("request data is required")


def handle_request(data, auth_token):
    """Validate, authenticate, and process an incoming API request."""
    _validate_request(data, auth_token)
    return process(data)

